<?php require_once dirname(__DIR__) . '/app/config.php';require_login();$id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT * FROM orders WHERE id=? AND user_id=?");$st->execute([$id,user()['id']]);$o=$st->fetch();if(!$o){http_response_code(404);exit('Không tìm thấy đơn hàng');}$st=$pdo->prepare("SELECT * FROM order_items WHERE order_id=?");$st->execute([$id]);$items=$st->fetchAll();header_html('Chi tiết đơn hàng');?><h1>Đơn hàng #<?=$id?></h1><p>Trạng thái: <strong><?=e($o['status'])?></strong></p><div class="card p-3"><table class="table"><thead><tr><th>Giáo trình</th><th>Giá</th><th>SL</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['book_title'])?></td><td><?=money($i['price'])?></td><td><?=$i['quantity']?></td></tr><?php endforeach;?></tbody></table><h4 class="text-end">Tổng: <?=money($o['total'])?></h4></div><?php footer_html();?>
